--    Every section is idempotent, so it is safe on a fresh project and on the
--    live one, and safe to run again.
--
--  WHAT IT IS
--    backend/migrations/001_security_indexes_and_features.sql
--    backend/migrations/003_tests_assigned_to.sql
--    backend/migrations/004_test_teachers_junction.sql
--    backend/migrations/005_exam_session_sync.sql
--    backend/migrations/006_scale_indexes.sql
--    backend/migrations/007_test_paper_pattern.sql
--    backend/migrations/008_question_type_taxonomy.sql
--    backend/migrations/009_test_results_published.sql
--    backend/migrations/010_reconcile_live_schema.sql
--    exam/backend/schema.sql
