--    re-run the generator rather than editing this file.
-- ============================================================================


-- ############################################################################
-- ##  backend/migrations/001_security_indexes_and_features.sql
-- ############################################################################

-- ============================================================================
--  EduCommand / IQ — Migration 001
--  Row Level Security, performance indexes, and columns for the new features.
--
--  HOW TO RUN
--    Supabase Dashboard -> SQL Editor -> paste this file -> Run.
--    It is idempotent: safe to run more than once.
--
--  IMPORTANT — why enabling RLS does not break the API
--    The NestJS backend connects with the SERVICE ROLE key, which bypasses RLS
--    entirely. These policies exist as defence-in-depth: if the anon/publishable
--    key ever leaks, a client still cannot read another student's answers or the
--    answer key. Nothing in the backend needs to change.
-- ============================================================================

begin;

-- ---------------------------------------------------------------------------
-- 0. Extensions
-- ---------------------------------------------------------------------------
create extension if not exists pg_trgm;

-- ---------------------------------------------------------------------------
-- 1. New columns
-- ---------------------------------------------------------------------------

-- Negative marking is currently only stored in the test description string.
-- These columns make it a real, gradable property (read by AttemptsService).
alter table public.tests add column if not exists negative_marking boolean not null default false;
alter table public.tests add column if not exists negative_marks   numeric(4,2) not null default 0;

-- Admin "Test Initiation" posts these two fields.
alter table public.tests add column if not exists subject      text;
alter table public.tests add column if not exists instructions text;

-- Manual QA / approval queue for AI-extracted questions.
-- Existing rows are grandfathered in as 'approved' so nothing disappears.
do $$
begin
  if not exists (
    select 1 from information_schema.columns
    where table_schema = 'public' and table_name = 'questions' and column_name = 'review_status'
  ) then
    alter table public.questions add column review_status text not null default 'approved';
    alter table public.questions add constraint questions_review_status_check
      check (review_status in ('pending', 'approved', 'rejected'));
  end if;
end $$;

alter table public.questions add column if not exists reviewed_by  uuid references public.users(id);
alter table public.questions add column if not exists reviewed_at  timestamptz;
alter table public.questions add column if not exists source       text;   -- 'manual' | 'csv' | 'pdf'

-- ---------------------------------------------------------------------------
-- 2. Integrity constraints the application logic already assumes
-- ---------------------------------------------------------------------------

-- AttemptsService upserts on (attempt_id, question_id).
do $$
begin
  if not exists (
    select 1 from pg_constraint where conname = 'answers_attempt_question_unique'
  ) then
    alter table public.answers
      add constraint answers_attempt_question_unique unique (attempt_id, question_id);
  end if;
end $$;

-- One attempt per student per test.
do $$
begin
  if not exists (
    select 1 from pg_constraint where conname = 'attempts_student_test_unique'
  ) then
    alter table public.attempts
      add constraint attempts_student_test_unique unique (student_id, test_id);
  end if;
end $$;

-- A student should not be assigned the same test twice.
do $$
begin
  if not exists (
    select 1 from pg_constraint where conname = 'test_assignments_test_student_unique'
  ) then
    alter table public.test_assignments
      add constraint test_assignments_test_student_unique unique (test_id, student_id);
  end if;
end $$;

-- ---------------------------------------------------------------------------
-- 3. Performance indexes
-- ---------------------------------------------------------------------------

-- Question Bank filtering — the composite covers the common
-- "active questions for subject X at difficulty Y" query.
create index if not exists idx_questions_active_subject_difficulty
  on public.questions (is_active, subject, difficulty);
create index if not exists idx_questions_topic        on public.questions (topic);
create index if not exists idx_questions_q_type       on public.questions (q_type);
create index if not exists idx_questions_created_at   on public.questions (created_at desc);
create index if not exists idx_questions_review_status on public.questions (review_status)
  where review_status <> 'approved';

-- Free-text search uses ILIKE '%...%', which only an index of this kind can serve.
create index if not exists idx_questions_text_trgm
  on public.questions using gin (question_text gin_trgm_ops);

-- Attempts & grading
create index if not exists idx_attempts_student   on public.attempts (student_id);
create index if not exists idx_attempts_test      on public.attempts (test_id, status);
create index if not exists idx_attempts_open      on public.attempts (status) where status = 'in_progress';
create index if not exists idx_answers_attempt    on public.answers (attempt_id);
create index if not exists idx_answers_question   on public.answers (question_id);

-- Test wiring
create index if not exists idx_test_questions_test    on public.test_questions (test_id, question_order);
create index if not exists idx_test_assignments_stud  on public.test_assignments (student_id);
create index if not exists idx_test_assignments_test  on public.test_assignments (test_id);
create index if not exists idx_tests_status           on public.tests (status, created_at desc);

-- Doubts queue & chat
create index if not exists idx_doubts_student    on public.doubts (student_id, created_at desc);
create index if not exists idx_doubts_queue      on public.doubts (status, accepted_by, created_at);
create index if not exists idx_doubt_messages    on public.doubt_messages (doubt_id, sent_at);

-- Batches
create index if not exists idx_batch_students_batch on public.batch_students (batch_id);
create index if not exists idx_batch_students_stud  on public.batch_students (student_id);
create index if not exists idx_batches_created_by   on public.batches (created_by);

-- ---------------------------------------------------------------------------
-- 4. Helper functions for RLS (security definer -> can read users table)
-- ---------------------------------------------------------------------------

create or replace function public.current_role()
returns text
language sql
stable
security definer
set search_path = public
as $$
  select role from public.users where id = auth.uid();
$$;

create or replace function public.is_staff()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(public.current_role() in ('teacher', 'admin'), false);
$$;

create or replace function public.is_admin()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(public.current_role() = 'admin', false);
$$;

-- ---------------------------------------------------------------------------
-- 5. Row Level Security
--    Enable on every table holding user data. service_role bypasses all of this.
-- ---------------------------------------------------------------------------

alter table public.users             enable row level security;
alter table public.batches           enable row level security;
alter table public.batch_students    enable row level security;
alter table public.questions         enable row level security;
alter table public.tests             enable row level security;
alter table public.test_questions    enable row level security;
alter table public.test_assignments  enable row level security;
alter table public.attempts          enable row level security;
alter table public.answers           enable row level security;
alter table public.doubts            enable row level security;
alter table public.doubt_messages    enable row level security;

-- Drop-then-create so the file can be re-run.
drop policy if exists users_self_read      on public.users;
drop policy if exists users_staff_read     on public.users;
drop policy if exists users_self_update    on public.users;
create policy users_self_read   on public.users for select using (id = auth.uid());
create policy users_staff_read  on public.users for select using (public.is_staff());
create policy users_self_update on public.users for update using (id = auth.uid()) with check (id = auth.uid());

drop policy if exists batches_staff_all on public.batches;
create policy batches_staff_all on public.batches for all using (public.is_staff()) with check (public.is_staff());

drop policy if exists batch_students_staff_all on public.batch_students;
drop policy if exists batch_students_self_read on public.batch_students;
create policy batch_students_staff_all on public.batch_students for all
  using (public.is_staff()) with check (public.is_staff());
create policy batch_students_self_read on public.batch_students for select
  using (student_id = auth.uid());

-- Questions: staff manage them. Students never select from this table directly —
-- the API strips correct_answer before it reaches them.
drop policy if exists questions_staff_all on public.questions;
create policy questions_staff_all on public.questions for all
  using (public.is_staff()) with check (public.is_staff());

drop policy if exists tests_staff_all       on public.tests;
drop policy if exists tests_student_read    on public.tests;
create policy tests_staff_all on public.tests for all
  using (public.is_staff()) with check (public.is_staff());
-- A student may see a test only if it is published AND assigned to them.
create policy tests_student_read on public.tests for select using (
  status = 'published'
  and exists (
    select 1 from public.test_assignments ta
    where ta.test_id = tests.id and ta.student_id = auth.uid()
  )
);

drop policy if exists test_questions_staff_all on public.test_questions;
create policy test_questions_staff_all on public.test_questions for all
  using (public.is_staff()) with check (public.is_staff());

drop policy if exists test_assignments_staff_all  on public.test_assignments;
drop policy if exists test_assignments_self_read  on public.test_assignments;
create policy test_assignments_staff_all on public.test_assignments for all
  using (public.is_staff()) with check (public.is_staff());
create policy test_assignments_self_read on public.test_assignments for select
  using (student_id = auth.uid());

-- Attempts: a student sees only their own; staff see all (for results pages).
drop policy if exists attempts_self_read   on public.attempts;
drop policy if exists attempts_staff_read  on public.attempts;
create policy attempts_self_read  on public.attempts for select using (student_id = auth.uid());
create policy attempts_staff_read on public.attempts for select using (public.is_staff());

-- Answers: reachable only through an attempt the caller owns.
drop policy if exists answers_self_read  on public.answers;
drop policy if exists answers_staff_read on public.answers;
create policy answers_self_read on public.answers for select using (
  exists (
    select 1 from public.attempts a
    where a.id = answers.attempt_id and a.student_id = auth.uid()
  )
);
create policy answers_staff_read on public.answers for select using (public.is_staff());

-- Doubts: the student who raised it, the teacher who owns it, any admin,
-- plus any teacher while it is still an unclaimed item in the queue.
drop policy if exists doubts_participant_read on public.doubts;
drop policy if exists doubts_participant_write on public.doubts;
create policy doubts_participant_read on public.doubts for select using (
  student_id = auth.uid()
  or accepted_by = auth.uid()
  or public.is_admin()
  or (public.current_role() = 'teacher' and accepted_by is null and status = 'pending')
);
create policy doubts_participant_write on public.doubts for update using (
  student_id = auth.uid() or accepted_by = auth.uid() or public.is_admin()
);

drop policy if exists doubt_messages_participant_read on public.doubt_messages;
drop policy if exists doubt_messages_participant_send on public.doubt_messages;
create policy doubt_messages_participant_read on public.doubt_messages for select using (
  exists (
    select 1 from public.doubts d
    where d.id = doubt_messages.doubt_id
      and (d.student_id = auth.uid() or d.accepted_by = auth.uid() or public.is_admin())
  )
);
create policy doubt_messages_participant_send on public.doubt_messages for insert with check (
  sender_id = auth.uid()
  and exists (
    select 1 from public.doubts d
    where d.id = doubt_messages.doubt_id
      and (d.student_id = auth.uid() or d.accepted_by = auth.uid() or public.is_admin())
  )
);

-- ---------------------------------------------------------------------------
-- 6. Spaced repetition + predictions
--    These tables were read by AnalyticsService but never created/written.
-- ---------------------------------------------------------------------------

create table if not exists public.spaced_repetition_state (
  id               uuid primary key default gen_random_uuid(),
  student_id       uuid not null references public.users(id) on delete cascade,
  question_id      uuid not null references public.questions(id) on delete cascade,
  repetitions      integer     not null default 0,
  ease_factor      numeric(4,2) not null default 2.5,
  interval_days    integer     not null default 0,
  due_at           timestamptz not null default now(),
  mastery_level    numeric(4,3) not null default 0,   -- 0..1
  priority_weight  numeric(6,3) not null default 1,   -- higher = revise sooner
  last_reviewed_at timestamptz,
  updated_at       timestamptz not null default now(),
  unique (student_id, question_id)
);

-- The table may predate this migration in an older shape, in which case the
-- create above was skipped. Add the columns the indexes below need, or the
-- index creation aborts this whole transaction. (010 finishes the job.)
alter table public.spaced_repetition_state add column if not exists repetitions     integer      not null default 0;
alter table public.spaced_repetition_state add column if not exists ease_factor     numeric(4,2) not null default 2.5;
alter table public.spaced_repetition_state add column if not exists interval_days   integer      not null default 0;
alter table public.spaced_repetition_state add column if not exists due_at          timestamptz  not null default now();
alter table public.spaced_repetition_state add column if not exists priority_weight numeric(6,3) not null default 1;

create index if not exists idx_srs_student_priority
  on public.spaced_repetition_state (student_id, priority_weight desc);
create index if not exists idx_srs_due on public.spaced_repetition_state (student_id, due_at);

create table if not exists public.predictions (
  id              uuid primary key default gen_random_uuid(),
  student_id      uuid not null references public.users(id) on delete cascade,
  subject         text not null,
  topic           text,
  predicted_score numeric(6,2) not null default 0,
  accuracy        numeric(5,2) not null default 0,
  sample_size     integer not null default 0,
  risk_flag       boolean not null default false,
  computed_at     timestamptz not null default now(),
  unique (student_id, subject, topic)
);

create index if not exists idx_predictions_student on public.predictions (student_id);
create index if not exists idx_predictions_risk    on public.predictions (risk_flag) where risk_flag;

alter table public.spaced_repetition_state enable row level security;
alter table public.predictions             enable row level security;

drop policy if exists srs_self_read         on public.spaced_repetition_state;
drop policy if exists srs_staff_read        on public.spaced_repetition_state;
create policy srs_self_read  on public.spaced_repetition_state for select using (student_id = auth.uid());
create policy srs_staff_read on public.spaced_repetition_state for select using (public.is_staff());

drop policy if exists predictions_self_read  on public.predictions;
drop policy if exists predictions_staff_read on public.predictions;
create policy predictions_self_read  on public.predictions for select using (student_id = auth.uid());
create policy predictions_staff_read on public.predictions for select using (public.is_staff());

-- ---------------------------------------------------------------------------
-- 7. Lectures / syllabus (backend module existed, tables may not)
-- ---------------------------------------------------------------------------

create table if not exists public.lectures (
  id               uuid primary key default gen_random_uuid(),
  subject          text not null,
  topic            text,
  title            text not null,
  drive_url        text,
  duration_minutes integer,
  uploaded_by      uuid references public.users(id),
  created_at       timestamptz not null default now()
);

create table if not exists public.syllabus_items (
  id          uuid primary key default gen_random_uuid(),
  subject     text not null,
  topic       text not null,
  subtopic    text,
  order_index integer not null default 0,
  created_at  timestamptz not null default now()
);

create index if not exists idx_lectures_subject on public.lectures (subject, topic);
create index if not exists idx_syllabus_subject on public.syllabus_items (subject, order_index);

alter table public.lectures       enable row level security;
alter table public.syllabus_items enable row level security;

drop policy if exists lectures_read      on public.lectures;
drop policy if exists lectures_staff_write on public.lectures;
create policy lectures_read        on public.lectures for select using (auth.uid() is not null);
create policy lectures_staff_write on public.lectures for all
  using (public.is_staff()) with check (public.is_staff());

drop policy if exists syllabus_read on public.syllabus_items;
create policy syllabus_read on public.syllabus_items for select using (auth.uid() is not null);

-- ---------------------------------------------------------------------------
-- 8. Storage: question-images bucket
-- ---------------------------------------------------------------------------

-- Public read (question diagrams are embedded in <img> tags), writes via service role only.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'question-images',
  'question-images',
  true,
  5242880,                                              -- 5 MB
  array['image/png','image/jpeg','image/gif','image/webp']
)
on conflict (id) do update
  set public             = excluded.public,
      file_size_limit    = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

drop policy if exists question_images_public_read on storage.objects;
create policy question_images_public_read on storage.objects
  for select using (bucket_id = 'question-images');

-- No insert/update/delete policy is defined on purpose: only the service role
-- (the NestJS backend) may write, so clients cannot upload arbitrary files.

commit;

-- ---------------------------------------------------------------------------
-- POST-MIGRATION NOTE
--   Set Cache-Control on the bucket for CDN caching. Supabase applies the value
--   supplied at upload time; the backend now sends `cacheControl: '31536000'`.
--   Existing objects keep their old header until re-uploaded.
-- ---------------------------------------------------------------------------


-- ############################################################################
-- ##  backend/migrations/003_tests_assigned_to.sql
-- ############################################################################

-- ============================================================================
--  Migration 003 — assigned_to on tests
--  Run in Supabase SQL Editor
-- ============================================================================

alter table public.tests
  add column if not exists assigned_to uuid references public.users(id);

-- Index so "find tests assigned to teacher X" is fast
create index if not exists idx_tests_assigned_to on public.tests (assigned_to);


-- ############################################################################
-- ##  backend/migrations/004_test_teachers_junction.sql
-- ############################################################################

-- ============================================================================
--  Migration 004 — test_teachers junction table (multi-teacher assignment)
--  Run in Supabase SQL Editor
-- ============================================================================

-- Junction table: one row per teacher assigned to a test
create table if not exists public.test_teachers (
  test_id    uuid not null references public.tests(id)    on delete cascade,
  teacher_id uuid not null references public.users(id)    on delete cascade,
  subject    text,                          -- optional: Physics / Chemistry / Mathematics
  assigned_at timestamptz not null default now(),
  primary key (test_id, teacher_id)
);

create index if not exists idx_test_teachers_test    on public.test_teachers (test_id);
create index if not exists idx_test_teachers_teacher on public.test_teachers (teacher_id);

-- RLS (service_role bypasses, same pattern as the rest of the schema)
alter table public.test_teachers enable row level security;

drop policy if exists test_teachers_staff_all on public.test_teachers;
create policy test_teachers_staff_all on public.test_teachers
  for all using (public.is_staff()) with check (public.is_staff());

-- Teachers can see their own assignments
drop policy if exists test_teachers_self_read on public.test_teachers;
create policy test_teachers_self_read on public.test_teachers
  for select using (teacher_id = auth.uid());


-- ############################################################################
-- ##  backend/migrations/005_exam_session_sync.sql
-- ############################################################################

-- ============================================================================
--  EduCommand / IQ — Migration 005
--  Makes the admin -> student -> secure-exam handoff actually hold together.
--
--  HOW TO RUN
--    Supabase Dashboard -> SQL Editor -> paste this file -> Run.
--    Idempotent: safe to run more than once.
--
--  WHY
--    1. The exam UI tracks a per-question palette state (answered / marked /
--       not_visited). Nothing persisted it, so a resumed attempt came back with
--       a blank palette even though the answers were still there.
--    2. Proctoring violations were posted to a service that does not own this
--       flow, against a table keyed on `exam_sessions` — a table the portal
--       never writes to. Violations now hang off `attempts`, like everything
--       else in this flow.
--    3. `test_assignments` had no uniqueness, so a student who belongs to two
--       batches that were both assigned the same test got two rows. Every read
--       used `.single()`, which fails on two rows — the dashboard listed the
--       test but starting it returned "You are not assigned to this test".
-- ============================================================================

begin;

-- ---------------------------------------------------------------------------
-- 1. Palette state for a resumed attempt
-- ---------------------------------------------------------------------------
alter table public.answers
  add column if not exists status text not null default 'not_visited';

do $$
begin
  if not exists (
    select 1 from pg_constraint where conname = 'answers_status_check'
  ) then
    alter table public.answers add constraint answers_status_check
      check (status in ('not_visited', 'not_answered', 'answered', 'marked', 'answered_marked'));
  end if;
end $$;

-- ---------------------------------------------------------------------------
-- 2. Proctoring violations, keyed on the attempt the portal actually creates
-- ---------------------------------------------------------------------------
create table if not exists public.attempt_violations (
  id          uuid primary key default gen_random_uuid(),
  attempt_id  uuid not null references public.attempts(id) on delete cascade,
  student_id  uuid not null references public.users(id) on delete cascade,
  type        text not null,
  detail      text,
  created_at  timestamptz not null default now()
);

create index if not exists idx_attempt_violations_attempt
  on public.attempt_violations (attempt_id, created_at);

alter table public.attempt_violations enable row level security;

-- The backend uses the service role key and bypasses RLS; these policies are
-- defence-in-depth for the case where a publishable key leaks.
drop policy if exists attempt_violations_self_read on public.attempt_violations;
create policy attempt_violations_self_read on public.attempt_violations
  for select using (student_id = auth.uid());

drop policy if exists attempt_violations_staff_read on public.attempt_violations;
create policy attempt_violations_staff_read on public.attempt_violations
  for select using (public.is_staff());

-- ---------------------------------------------------------------------------
-- 3. One assignment row per (test, student)
-- ---------------------------------------------------------------------------

-- Collapse existing duplicates first: keep the widest window, drop the rest.
with ranked as (
  select id,
         row_number() over (
           partition by test_id, student_id
           order by scheduled_start asc nulls first, scheduled_end desc nulls last, id
         ) as rn
  from public.test_assignments
)
delete from public.test_assignments ta
using ranked r
where ta.id = r.id and r.rn > 1;

do $$
begin
  if not exists (
    select 1 from pg_constraint where conname = 'test_assignments_test_student_unique'
  ) then
    alter table public.test_assignments
      add constraint test_assignments_test_student_unique unique (test_id, student_id);
  end if;
end $$;

commit;


-- ############################################################################
-- ##  backend/migrations/006_scale_indexes.sql
-- ############################################################################

-- ============================================================================
--  EduCommand / IQ — Migration 006
--  Indexes for the queries that only start to hurt at cohort scale (~1000
--  students sitting the same paper).
--
--  HOW TO RUN
--    Supabase Dashboard -> SQL Editor -> paste this file -> Run.
--    Idempotent: safe to run more than once.
--
--  WHY
--    Result pages, leaderboards and the per-attempt rank all reduce to counting
--    or scanning `attempts` filtered by test and status, and `answers` filtered
--    by attempt. With one row per student per test those are the tables that
--    grow fastest, and every one of these queries was doing a sequential scan.
-- ============================================================================

begin;

-- ---------------------------------------------------------------------------
-- Rank + percentile: three COUNT(*) queries per result view, all of the form
--   where test_id = ? and status = 'submitted' and total_score > ?
-- Including total_score makes them index-only.
-- ---------------------------------------------------------------------------
create index if not exists idx_attempts_test_status_score
  on public.attempts (test_id, status, total_score);

-- The student's own history list, newest first.
create index if not exists idx_attempts_student_started
  on public.attempts (student_id, started_at desc);

-- Leaderboard aggregate: every submitted attempt, paged by primary key.
create index if not exists idx_attempts_submitted
  on public.attempts (status, id) where status = 'submitted';

-- ---------------------------------------------------------------------------
-- Grading writes one row per answered question and the result page reads them
-- all back; the per-question difficulty breakdown reads them across every
-- attempt on a test.
-- ---------------------------------------------------------------------------
create index if not exists idx_answers_attempt_question
  on public.answers (attempt_id, question_id);

create index if not exists idx_answers_question_correct
  on public.answers (question_id, is_correct);

-- ---------------------------------------------------------------------------
-- Assignment lookups run on every exam start and on every paper fetch.
-- ---------------------------------------------------------------------------
create index if not exists idx_test_assignments_student_test
  on public.test_assignments (student_id, test_id);

create index if not exists idx_test_assignments_test_window
  on public.test_assignments (test_id, scheduled_start, scheduled_end);

-- ---------------------------------------------------------------------------
-- Spaced repetition and predictions are rewritten after every submission.
-- ---------------------------------------------------------------------------
create index if not exists idx_srs_student_question
  on public.spaced_repetition_state (student_id, question_id);

create index if not exists idx_predictions_student_subject
  on public.predictions (student_id, subject);

-- ---------------------------------------------------------------------------
-- Proctoring: the strike counter runs `count(*) where attempt_id = ?` on every
-- violation event, and a tab-switching student can generate a lot of those.
-- ---------------------------------------------------------------------------
create index if not exists idx_attempt_violations_count
  on public.attempt_violations (attempt_id);

-- ---------------------------------------------------------------------------
-- Staff lists: the CRM pages sort by name within a role.
-- ---------------------------------------------------------------------------
create index if not exists idx_users_role_name
  on public.users (role, full_name);

commit;


-- ############################################################################
-- ##  backend/migrations/007_test_paper_pattern.sql
-- ############################################################################

-- ============================================================================
--  EduCommand / IQ — Migration 007
--  Separates a test's *paper pattern* from its *type*.
--
--  HOW TO RUN
--    Supabase Dashboard -> SQL Editor -> paste this file -> Run.
--    Idempotent: safe to run more than once.
--
--  WHY
--    `tests.t_type` is the enum `public.test_type`, whose members are
--    quiz | mock_test | assignment | exam.
--
--    The admin console has always sent the exam *pattern* in that field —
--    'jee_main', 'jee_advanced', 'custom' — none of which are enum members. So
--    every "Create Test Shell" hit
--        22P02: invalid input value for enum test_type: "jee_main"
--    and failed. The pattern is genuinely a second axis: a JEE Main mock and a
--    custom mock are both `mock_test`, but they have different section layouts
--    and different publish rules (JEE Main enforces 20 MCQ + 10 numerical per
--    subject), so it needs its own column rather than overloading the enum.
--
--    Migration 002 attempted something similar with a `test_type text` column,
--    but naming a column after the enum *type* invites exactly this confusion,
--    and it was never applied to the live database. This supersedes it.
-- ============================================================================

begin;

-- ---------------------------------------------------------------------------
-- 1. The pattern column
-- ---------------------------------------------------------------------------
alter table public.tests
  add column if not exists paper_pattern text;

do $$
begin
  if not exists (
    select 1 from pg_constraint where conname = 'tests_paper_pattern_check'
  ) then
    alter table public.tests add constraint tests_paper_pattern_check
      check (paper_pattern is null or paper_pattern in ('jee_main', 'jee_advanced', 'jee_advanced_p2', 'neet', 'custom'));
  end if;
end $$;

-- Section layout for a custom paper, and the preset snapshot for a templated
-- one. Stored as JSON text, matching how the console already serialises them.
alter table public.tests
  add column if not exists preset_config   text;

alter table public.tests
  add column if not exists custom_sections text;

-- ---------------------------------------------------------------------------
-- 2. Backfill
-- ---------------------------------------------------------------------------
-- Before this column existed the console wrote the pattern into the title and
-- the generated instructions ("Pattern: JEE Main"). Read it back from there —
-- a blanket 'custom' turned every existing JEE / NEET paper into a custom one
-- and dropped its section quotas. Only what cannot be recognised is 'custom'.
update public.tests
   set paper_pattern = case
         when lower(coalesce(title, '') || ' ' || coalesce(instructions, '') || ' ' || coalesce(description, ''))
              ~ 'jee[ _]?adv' and lower(coalesce(title, '') || ' ' || coalesce(instructions, ''))
              ~ 'paper[ _-]?(2|ii)\M' then 'jee_advanced_p2'
         when lower(coalesce(title, '') || ' ' || coalesce(instructions, '') || ' ' || coalesce(description, ''))
              ~ 'jee[ _]?adv' then 'jee_advanced'
         when lower(coalesce(title, '') || ' ' || coalesce(instructions, '') || ' ' || coalesce(description, ''))
              ~ 'jee[ _]?main' then 'jee_main'
         when lower(coalesce(title, '') || ' ' || coalesce(instructions, '') || ' ' || coalesce(description, ''))
              ~ 'neet' then 'neet'
         else 'custom'
       end
 where paper_pattern is null;

-- ---------------------------------------------------------------------------
-- 3. Index — the console filters the library by pattern
-- ---------------------------------------------------------------------------
create index if not exists idx_tests_paper_pattern
  on public.tests (paper_pattern);

commit;


-- ############################################################################
-- ##  backend/migrations/008_question_type_taxonomy.sql
-- ############################################################################

-- ============================================================================
--  EduCommand / IQ — Migration 008
--  Lets the PDF pipeline file questions by Subject -> Topic -> Question Type.
--
--  HOW TO RUN
--    Supabase Dashboard -> SQL Editor -> paste this file -> Run.
--    Idempotent: safe to run more than once.
--
--  WHY
--    The PDF processor used to write `q_type = 'single_correct'` for every
--    question it extracted, whatever the paper actually asked. A numerical
--    question therefore reached students as a four-option MCQ with placeholder
--    options — unanswerable — and the question bank could not be filtered by
--    answer format at all, so a JEE Advanced section that needs six
--    multi-correct questions had to be filled by reading each one.
--
--    classify.py now decides the type from the paper's own section banners,
--    its printed answer key and the classifier AI, and writes one of the four
--    values the API's write contract accepts (QUESTION_TYPES in
--    dto/question.dto.ts). Two things have to be true in the database for that
--    to land:
--
--      1. `questions.q_type` must accept all four values. Where it is an enum,
--         a value the type does not know fails the whole insert batch with
--         22P02 — the same class of failure migration 007 fixed for
--         `tests.t_type`.
--      2. Browsing the new hierarchy needs an index that matches it.
--
--  NOTE ON EXISTING ROWS
--    Questions extracted before this migration were all stored as
--    'single_correct' and the evidence for their real type was never kept, so
--    there is nothing to backfill from. They stay as they are; a reviewer
--    corrects them in the Review Queue.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 1. Make sure every question type is a legal value
-- ---------------------------------------------------------------------------
-- Deliberately outside the transaction below: `alter type ... add value` may
-- not be used in the same transaction that goes on to write the new label.
do $$
declare
  type_name text;
  wanted    text;
begin
  -- The enum backing q_type, if it is an enum at all (it may be plain text).
  select t.typname
    into type_name
    from pg_attribute   a
    join pg_class       c on c.oid = a.attrelid
    join pg_namespace   n on n.oid = c.relnamespace
    join pg_type        t on t.oid = a.atttypid
   where n.nspname = 'public'
     and c.relname = 'questions'
     and a.attname = 'q_type'
     and t.typtype = 'e';

  if type_name is null then
    raise notice 'questions.q_type is not an enum — nothing to extend.';
    return;
  end if;

  foreach wanted in array array['single_correct', 'multi_correct', 'numerical', 'assertion']
  loop
    if not exists (
      select 1
        from pg_enum e
        join pg_type t on t.oid = e.enumtypid
       where t.typname = type_name
         and e.enumlabel = wanted
    ) then
      execute format('alter type public.%I add value %L', type_name, wanted);
      raise notice 'Added % to enum %', wanted, type_name;
    end if;
  end loop;
end $$;

begin;

-- ---------------------------------------------------------------------------
-- 2. Index for the Subject -> Topic -> Question Type drill-down
-- ---------------------------------------------------------------------------
-- Filling a paper's sections asks "approved Physics / Rotational Motion /
-- multi_correct questions". Migration 001 indexed those columns separately,
-- which makes Postgres pick one and filter the rest by hand; the composite
-- serves the whole predicate, and the leading column still serves a
-- subject-only or subject+topic query.
create index if not exists idx_questions_subject_topic_q_type
  on public.questions (subject, topic, q_type);

commit;


-- ############################################################################
-- ##  backend/migrations/009_test_results_published.sql
-- ############################################################################

-- ============================================================================
--  Migration 009 — Test Results Approval / Published Status
--  Run in Supabase SQL Editor if desired (backend also supports fallback)
-- ============================================================================

alter table public.tests
  add column if not exists results_published boolean not null default false;

create index if not exists idx_tests_results_published on public.tests (results_published);


-- ############################################################################
-- ##  backend/migrations/010_reconcile_live_schema.sql
-- ############################################################################

-- ============================================================================
--  EduCommand / IQ — Migration 010
--  Brings tables that existed BEFORE migration 001 up to the shape the code uses.
--
--  HOW TO RUN
--    Supabase Dashboard -> SQL Editor -> paste this file -> Run.
--    Idempotent: safe to run more than once. Run after 001-009.
--
--  WHY
--    Migration 001 creates `spaced_repetition_state`, `predictions` and
--    `syllabus_items` with `create table if not exists`. On the live project
--    those tables already existed in an older shape, so 001 skipped them and the
--    columns and unique keys the code relies on were never added:
--
--      spaced_repetition_state: repetitions, ease_factor, interval_days, due_at,
--        last_reviewed_at, updated_at, unique (student_id, question_id)
--        -> every submit logged "SRS upsert failed"; /analytics/revision-due 500'd
--      predictions: accuracy, sample_size, unique (student_id, subject, topic)
--        -> risk predictions were never written
--      syllabus_items: subtopic
--        -> /lectures/syllabus/:subject 500'd
--
--    It also re-asserts the three unique keys the exam flow upserts on, in case
--    001 was only partly applied. Without `answers_attempt_question_unique`
--    every answer save fails ("no unique or exclusion constraint matching the
--    ON CONFLICT specification") and students submit blank papers.
-- ============================================================================

begin;

-- ---------------------------------------------------------------------------
-- 1. Spaced repetition
-- ---------------------------------------------------------------------------
alter table public.spaced_repetition_state add column if not exists repetitions      integer      not null default 0;
alter table public.spaced_repetition_state add column if not exists ease_factor      numeric(4,2) not null default 2.5;
alter table public.spaced_repetition_state add column if not exists interval_days    integer      not null default 0;
alter table public.spaced_repetition_state add column if not exists due_at           timestamptz  not null default now();
alter table public.spaced_repetition_state add column if not exists last_reviewed_at timestamptz;
alter table public.spaced_repetition_state add column if not exists updated_at       timestamptz  not null default now();
alter table public.spaced_repetition_state add column if not exists mastery_level    numeric(4,3) not null default 0;
alter table public.spaced_repetition_state add column if not exists priority_weight  numeric(6,3) not null default 1;

-- Keep the newest row per (student, question) before adding the key.
with ranked as (
  select id, row_number() over (partition by student_id, question_id order by id desc) as rn
  from public.spaced_repetition_state
)
delete from public.spaced_repetition_state s using ranked r where s.id = r.id and r.rn > 1;

do $$
begin
  if not exists (
    select 1 from pg_constraint
    where conrelid = 'public.spaced_repetition_state'::regclass and contype = 'u'
      and conname = 'spaced_repetition_state_student_question_unique'
  ) and not exists (
    select 1 from pg_constraint
    where conrelid = 'public.spaced_repetition_state'::regclass and contype = 'u'
      and conname = 'spaced_repetition_state_student_id_question_id_key'
  ) then
    alter table public.spaced_repetition_state
      add constraint spaced_repetition_state_student_question_unique unique (student_id, question_id);
  end if;
end $$;

create index if not exists idx_srs_due on public.spaced_repetition_state (student_id, due_at);

-- ---------------------------------------------------------------------------
-- 2. Predictions
-- ---------------------------------------------------------------------------
alter table public.predictions add column if not exists accuracy    numeric(5,2) not null default 0;
alter table public.predictions add column if not exists sample_size integer      not null default 0;

with ranked as (
  select id, row_number() over (partition by student_id, subject, topic order by computed_at desc, id desc) as rn
  from public.predictions
)
delete from public.predictions p using ranked r where p.id = r.id and r.rn > 1;

do $$
begin
  if not exists (
    select 1 from pg_constraint
    where conrelid = 'public.predictions'::regclass and contype = 'u'
      and conname in ('predictions_student_subject_topic_unique', 'predictions_student_id_subject_topic_key')
  ) then
    -- NULLS NOT DISTINCT (Postgres 15+): a subject-level row has topic = null,
    -- and two nulls must still collide or the upsert inserts a duplicate.
    alter table public.predictions
      add constraint predictions_student_subject_topic_unique
      unique nulls not distinct (student_id, subject, topic);
  end if;
end $$;

-- ---------------------------------------------------------------------------
-- 3. Syllabus
-- ---------------------------------------------------------------------------
alter table public.syllabus_items add column if not exists subtopic text;

-- ---------------------------------------------------------------------------
-- 4. The keys the exam flow upserts on (also in 001; re-asserted here)
-- ---------------------------------------------------------------------------
with ranked as (
  select id, row_number() over (partition by attempt_id, question_id order by id desc) as rn
  from public.answers
)
delete from public.answers a using ranked r where a.id = r.id and r.rn > 1;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'answers_attempt_question_unique') then
    alter table public.answers
      add constraint answers_attempt_question_unique unique (attempt_id, question_id);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'attempts_student_test_unique') then
    alter table public.attempts
      add constraint attempts_student_test_unique unique (student_id, test_id);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'test_assignments_test_student_unique') then
    alter table public.test_assignments
      add constraint test_assignments_test_student_unique unique (test_id, student_id);
  end if;
end $$;

-- ---------------------------------------------------------------------------
-- 5. Paper patterns: JEE Advanced has two papers
-- ---------------------------------------------------------------------------
-- 007 first allowed jee_main | jee_advanced | neet | custom. JEE Advanced is two
-- papers with different blueprints (backend/src/modules/tests/exam-patterns.data.json),
-- so 'jee_advanced' is Paper 1 and 'jee_advanced_p2' is Paper 2.
alter table public.tests drop constraint if exists tests_paper_pattern_check;
alter table public.tests add constraint tests_paper_pattern_check
  check (paper_pattern is null or paper_pattern in ('jee_main', 'jee_advanced', 'jee_advanced_p2', 'neet', 'custom'));

commit;

notify pgrst, 'reload schema';


-- ############################################################################
-- ##  exam/backend/schema.sql
-- ############################################################################

-- Secure Exam Module Schema
--
-- Idempotent: safe to run more than once. Run migrations/001_exam_hardening.sql
-- after it — that file replaces the policies below with owner-scoped ones.

-- Table for tracking secure exam sessions
CREATE TABLE IF NOT EXISTS public.exam_sessions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    student_id UUID NOT NULL,
    exam_id UUID NOT NULL,
    started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    ends_at TIMESTAMPTZ NOT NULL,
    status TEXT NOT NULL CHECK (status IN ('in_progress', 'submitted', 'auto_submitted', 'violation_terminated')) DEFAULT 'in_progress',
    submitted_at TIMESTAMPTZ,
    score NUMERIC(5,2),
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table for tracking individual responses in real-time
CREATE TABLE IF NOT EXISTS public.exam_responses (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    session_id UUID NOT NULL REFERENCES public.exam_sessions(id) ON DELETE CASCADE,
    question_id TEXT NOT NULL,
    selected_answer JSONB,
    status TEXT NOT NULL CHECK (status IN ('not_visited', 'not_answered', 'answered', 'marked', 'answered_marked')) DEFAULT 'not_visited',
    time_spent_seconds INTEGER DEFAULT 0,
    last_updated_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE(session_id, question_id)
);

-- Table for tracking cheating/violation events
CREATE TABLE IF NOT EXISTS public.exam_violations (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    session_id UUID NOT NULL REFERENCES public.exam_sessions(id) ON DELETE CASCADE,
    type TEXT NOT NULL CHECK (type IN ('tab_hidden', 'window_blur', 'fullscreen_exit', 'devtools_suspected')),
    timestamp TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    duration_ms INTEGER,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- RLS: enabled with no permissive policies. The exam API uses the service role
-- key, which bypasses RLS; 001_exam_hardening.sql adds read-own policies.
-- (The original `FOR ALL USING (true)` policies opened these tables to anyone
-- holding the anon key, so they are no longer created here.)
ALTER TABLE public.exam_sessions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.exam_responses ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.exam_violations ENABLE ROW LEVEL SECURITY;


-- ############################################################################
-- ##  exam/backend/migrations/001_exam_hardening.sql
-- ############################################################################

-- ============================================================================
--  Secure Exam Module — Migration 001 (hardening)
--
--  HOW TO RUN
--    Supabase Dashboard -> SQL Editor -> paste this file -> Run.
--    Idempotent: safe to run more than once. Run it after schema.sql.
--
--  WHY
--    1. schema.sql granted `FOR ALL USING (true)` on all three exam tables.
--       RLS policies apply to the `anon` and `authenticated` roles — the service
--       role bypasses RLS entirely and never needed them — so those policies did
--       not protect the service, they opened the tables to anyone holding the
--       publishable anon key. That is every student, and it means reading or
--       rewriting somebody else's live exam session from the browser console.
--    2. `exam_sessions` had no uniqueness on (student_id, exam_id), so a
--       double-clicked "Start" created two sessions for the same paper and the
--       `maybeSingle()` read that looks for an existing one then errors outright.
--    3. The violation counter and response lookups had no supporting index.
-- ============================================================================

begin;

-- ---------------------------------------------------------------------------
-- 1. Replace the permissive policies with owner-scoped ones
-- ---------------------------------------------------------------------------
drop policy if exists "Service Role full access to exam_sessions"  on public.exam_sessions;
drop policy if exists "Service Role full access to exam_responses" on public.exam_responses;
drop policy if exists "Service Role full access to exam_violations" on public.exam_violations;

alter table public.exam_sessions   enable row level security;
alter table public.exam_responses  enable row level security;
alter table public.exam_violations enable row level security;

-- A student may read their own sessions and nothing else. All writes go through
-- the API, which uses the service role key and bypasses RLS; there is
-- deliberately no insert/update policy for `authenticated`.
drop policy if exists exam_sessions_self_read on public.exam_sessions;
create policy exam_sessions_self_read on public.exam_sessions
  for select using (student_id = auth.uid());

drop policy if exists exam_responses_self_read on public.exam_responses;
create policy exam_responses_self_read on public.exam_responses
  for select using (
    exists (
      select 1 from public.exam_sessions s
      where s.id = exam_responses.session_id and s.student_id = auth.uid()
    )
  );

drop policy if exists exam_violations_self_read on public.exam_violations;
create policy exam_violations_self_read on public.exam_violations
  for select using (
    exists (
      select 1 from public.exam_sessions s
      where s.id = exam_violations.session_id and s.student_id = auth.uid()
    )
  );

-- ---------------------------------------------------------------------------
-- 2. One session per (student, exam)
-- ---------------------------------------------------------------------------

-- Collapse any duplicates a racing start already created: keep the earliest.
with ranked as (
  select id,
         row_number() over (
           partition by student_id, exam_id order by started_at asc, id
         ) as rn
  from public.exam_sessions
)
delete from public.exam_sessions es
using ranked r
where es.id = r.id and r.rn > 1;

do $$
begin
  if not exists (
    select 1 from pg_constraint where conname = 'exam_sessions_student_exam_unique'
  ) then
    alter table public.exam_sessions
      add constraint exam_sessions_student_exam_unique unique (student_id, exam_id);
  end if;
end $$;

-- ---------------------------------------------------------------------------
-- 3. Indexes for the hot reads
-- ---------------------------------------------------------------------------
create index if not exists idx_exam_sessions_student
  on public.exam_sessions (student_id, exam_id);

create index if not exists idx_exam_sessions_open
  on public.exam_sessions (status, ends_at) where status = 'in_progress';

create index if not exists idx_exam_responses_session
  on public.exam_responses (session_id);

-- Backs the `count(*) where session_id = ?` the violation limiter runs on every
-- strike; without it each proctoring event scanned the whole table.
create index if not exists idx_exam_violations_session
  on public.exam_violations (session_id);

commit;


-- ############################################################################
-- ##  Make PostgREST see the new tables/columns immediately
-- ############################################################################
notify pgrst, 'reload schema';

-- Quick check — every row should say true.
select 'tests.paper_pattern' as item, exists (select 1 from information_schema.columns where table_schema='public' and table_name='tests' and column_name='paper_pattern') as ok
union all select 'tests.results_published', exists (select 1 from information_schema.columns where table_schema='public' and table_name='tests' and column_name='results_published')
union all select 'answers.status',          exists (select 1 from information_schema.columns where table_schema='public' and table_name='answers' and column_name='status')
union all select 'srs.due_at',              exists (select 1 from information_schema.columns where table_schema='public' and table_name='spaced_repetition_state' and column_name='due_at')
union all select 'answers unique key',      exists (select 1 from pg_constraint where conname='answers_attempt_question_unique')
union all select 'attempts unique key',     exists (select 1 from pg_constraint where conname='attempts_student_test_unique')
union all select 'attempt_violations',      to_regclass('public.attempt_violations') is not null
union all select 'exam_sessions',           to_regclass('public.exam_sessions') is not null
union all select 'is_staff()',              to_regprocedure('public.is_staff()') is not null;
